  box-sizing: border-box;
  font-family: 'G마켓 산스 TTF', sans-serif;
}

html,
body,
#root {
  width: 100%;
  min-height: 100%;
  margin: 0;
  background: transparent !important;
  font-family: 'G마켓 산스 TTF', sans-serif;
}

button,
input,
select,
textarea {
  font-family: inherit;
  font: inherit;
}

body {
  color: #292c35;
  font-size: 13px;
}

button {
  -webkit-app-region: no-drag;
}

.app {
  margin: 0;
  padding: 0;
  background: transparent;
}

/* =========================
   상단 헤더
   ========================= */

.calendar-header {
  position: relative;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.calendar-header.drag-area {
  -webkit-app-region: drag;
}

.calendar-header.no-drag,
.calendar-header button {
  -webkit-app-region: no-drag;
}

.today-info {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  margin-right: auto;
}

.today-date {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding-top: 70px;
  color: #000;
  font-family: '조선굴림체', sans-serif;
  font-size: 30px;
  font-weight: 550;
  line-height: 1.1;
}

.today-prefix,
.today-weekday {
  display: inline-block;
  font-family: '조선굴림체', sans-serif;
  line-height: inherit;
}

.today-weekday {
  color: #d54141;
  font-size: 36px;
  font-weight: 700;
  line-height: 1.1;
}

/* 월 이동 및 월 표시 */

.month-title {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: flex-start;
  width: 120px;
  min-width: 120px;
  gap: 0;
  padding-top: 30px;
  margin-right: 0;
}

.month-arrows {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  margin-bottom: 4px;
}

.month-arrows .nav-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  color: #353a47;
  font-size: 24px;
  cursor: pointer;
  -webkit-app-region: no-drag;
}

.month-arrows .nav-btn:hover {
  background: transparent;
}

.month-label {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
  gap: 2px;
}

.month-label .month-year {
  display: block;
  order: 1;
  width: 100%;
  color: #8b8b96;
  font-size: 13px;
  font-weight: 400;
  line-height: 1.2;
  text-align: center;
}

.month-label .month-number {
  display: block;
  order: 2;
  padding: 0;
  color: #292936;
  font-size: 40px;
  font-weight: 700;
  line-height: 1.1;
  text-align: center;
}

/* =========================
   달력 레이아웃
   ========================= */

.calendar,
.weekdays,
.calendar-days {
  width: 100%;
  font-weight: 400;
}

.weekdays {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 3px;
  margin-bottom: 4px;
  font-weight: 600;
  text-align: center;
}

.weekdays > div {
  padding: 6px 0;
}

.calendar-days {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.calendar-week {
  position: relative;
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  align-items: stretch;
  gap: 3px;
  min-width: 0;
}

.sun {
  color: #e45e70;
}

.sat {
  color: #4e79dc;
}

/* 날짜 칸 */

.empty-day {
  min-height: 56px;
}

.calendar-day {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-start;
  width: 100%;
  min-width: 0;
  min-height: 80px;
  padding: 8px;
  overflow: visible;
  border: 1px solid rgb(130 140 155 / 20%);
  border-radius: 8px;
  background: transparent;
  text-align: left;
  vertical-align: top;
  cursor: pointer;
}

.calendar-day:hover {
  background: rgb(255 255 255 / 35%);
  border-color: rgb(100 125 180 / 45%);
}

.day-number {
  display: block;
  margin-bottom: 5px;
  font-size: 14px;
  line-height: 1.3;
  text-align: left;
}

.calendar-day.today {
  color: #d54141;
  font-size: 22px;
  font-weight: 500;
}

.calendar-day.today .day-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 22px;
  padding: 0 4px;
  border-radius: 50%;
  background: #d54141;
  color: #fff;
  font-family: 'Gmarket Sans';
}

.day-number.sun {
  color: #d54141;
}

.day-number.sat {
  color: #5689df;
}

.day-heading {
  display: flex;
  align-items: baseline;
  gap: 3px;
  width: 100%;
  min-width: 0;
}

.holiday-name {
  min-width: 0;
  overflow: hidden;
  color: #d54141;
  font-size: 13px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 일정 표시 */

.event-list {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  width: 100%;
  margin-top: 8px;
  gap: 3px;
  overflow: hidden;
}

.event-dot {
  display: block;
  padding: 2px 3px;
  overflow: hidden;
  border-left: 3px solid var(--event-color);
  border-radius: 2px;
  background: rgb(255 255 255 / 72%);
  color: #343744;
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 여러 날짜에 걸친 일정 막대 */

.week-bars {
  position: absolute;
  top: 36px;
  right: 0;
  left: 0;
  z-index: 3;
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  grid-auto-rows: 20px;
  column-gap: 3px;
  row-gap: 3px;
  pointer-events: none;
}

.multi-day-bar {
  position: relative;
  z-index: 1;
  display: block;
  width: 100%;
  min-width: 0;
  height: 20px;
  margin: 0;
  padding: 2px 5px;
  overflow: hidden;
  border: 0;
  border-radius: 0;
  color: #343744;
  font-size: 12px;
  line-height: 16px;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
  cursor: pointer;
  pointer-events: auto;
}

.multi-day-bar.bar-start {
  border-radius: 5px 0 0 5px;
}

.multi-day-bar.bar-end {
  border-radius: 0 5px 5px 0;
}

.multi-day-bar.bar-start.bar-end {
  border-radius: 5px;
}

/* =========================
   일정 추가 / 수정 모달
   ========================= */

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 12px;
  background: rgb(20 25 40 / 30%);
}

.event-modal {
  width: 100%;
  max-width: 380px;
  max-height: calc(100vh - 24px);
  overflow-y: auto;
  padding: 22px;
  border: 1px solid #e5eaf4;
  border-radius: 20px;
  background: #fff;
  box-shadow: 0 16px 50px rgb(25 35 60 / 22%);
  font-family: 'Gmarket Sans';
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.event-modal::-webkit-scrollbar {
  display: none;
}

.modal-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 12px;
}

.modal-header h2 {
  margin: 0 0 5px;
  font-size: 21px;
}

.modal-header p {
  margin: 0;
  color: #777e8e;
  font-size: 12px;
}

.close-btn {
  border: 0;
  background: transparent;
  color: #6d7481;
  font-size: 25px;
  cursor: pointer;
}

/* 입력 필드 */

.field {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-bottom: 14px;
  color: #4b5261;
  font-size: 12px;
  font-weight: 600;
}

.field input,
.field select,
.field textarea {
  width: 100%;
  min-width: 0;
  padding: 10px 11px;
  border: 1px solid #dfe5ef;
  border-radius: 9px;
  outline: none;
  background: #fff;
  color: #292c35;
  font-size: 12px;
  font-weight: 400;
}

.field input:focus,
.field select:focus,
.field textarea:focus {
  border-color: #92b7f5;
  box-shadow: 0 0 0 3px rgb(146 183 245 / 18%);
}

.field-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

/* 일정 색상 팔레트 */

.color-options {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
}

.color-choice {
  width: 25px;
  height: 25px;
  padding: 0;
  border: 2px solid #fff;
  border-radius: 50%;
  box-shadow: 0 0 0 1px #d8dce5;
  cursor: pointer;
}

.color-choice.active {
  box-shadow: 0 0 0 2px #505b72;
}

.color-add-button {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  min-width: 28px;
  margin: 0;
  padding: 0;
  border: 1.5px dashed #b7bbc4;
  border-radius: 50%;
  background: #fff;
  color: #7c8494;
  font-family: Arial, sans-serif;
  font-size: 22px;
  font-weight: 400;
  line-height: 1;
  text-align: center;
  cursor: pointer;
  transition: background 0.18s ease, border-color 0.18s ease, transform 0.18s ease;
}

.color-add-button:hover {
  transform: scale(1.08);
  border-color: #8db8ff;
  background: #f2f5ff;
  color: #668edb;
}

.color-add-button:active {
  transform: scale(0.94);
}

.color-add-plus {
  display: block;
  font-family: Arial, sans-serif;
  font-size: 22px;
  font-weight: 400;
  line-height: 1;
  transform: translateY(-1px);
}

/* 새 색상 추가 팝업 */

.color-picker-popup {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  flex-wrap: nowrap;
  gap: 16px;
  width: 100%;
  height: auto;
  margin-top: 12px;
  padding: 16px;
  border: 1px solid #e8eaf0;
  border-radius: 16px;
  background: #fff;
  box-shadow: 0 8px 24px rgb(60 70 100 / 10%);
  overflow: visible;
}

.color-popup-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.color-popup-heading strong {
  color: #30384a;
  font-size: 14px;
}

.color-popup-heading p {
  margin: 5px 0 0;
  color: #969dad;
  font-size: 11px;
}

.color-preview {
  width: 42px;
  height: 42px;
  flex-shrink: 0;
  border: 1px solid rgb(0 0 0 / 6%);
  border-radius: 13px;
  box-shadow: inset 0 0 0 1px rgb(255 255 255 / 25%);
}

.hex-label {
  display: flex;
  flex-direction: column;
  gap: 7px;
  color: #687083;
  font-size: 12px;
  font-weight: 600;
}

.hex-input-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 42px;
  padding: 0 12px;
  border: 1px solid #e5e8ef;
  border-radius: 11px;
  background: #fafbfe;
}

.hex-input-wrap:focus-within {
  border-color: #8db8ff;
  box-shadow: 0 0 0 3px rgb(141 184 255 / 16%);
}

.hex-input-wrap span {
  color: #9ba2b1;
  font-size: 14px;
}

.hex-input-wrap input {
  width: 100%;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: #41495b;
  font-family: Consolas, monospace;
  font-size: 14px;
  letter-spacing: 1px;
}

.quick-colors {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
}

.quick-color {
  width: 27px;
  height: 27px;
  padding: 0;
  border: 2px solid #fff;
  border-radius: 50%;
  box-shadow: 0 0 0 1px #e5e8ef;
  cursor: pointer;
  transition: transform 0.15s ease;
}

.quick-color:hover {
  transform: scale(1.13);
}

.color-popup-actions {
  display: flex;
  flex-direction: row;
  justify-content: flex-end;
  align-items: center;
  flex-shrink: 0;
  gap: 10px;
  width: 100%;
  min-height: 48px;
  margin-top: 8px;
  padding-top: 12px;
  border-top: 1px solid #f0f1f5;
}

.color-popup-actions button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  min-width: 76px;
  height: 36px;
  padding: 0 16px;
  border: 1px solid transparent;
  border-radius: 10px;
  font-family: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease;
}

.color-popup-actions .color-cancel-btn {
  background: #f1f2f6;
  color: #596174;
}

.color-popup-actions .color-cancel-btn:hover {
  background: #e9ebf1;
}

.color-popup-actions .color-confirm-btn {
  background: #8db8ff;
  color: #fff;
  box-shadow: 0 2px 5px rgb(100 145 220 / 15%);
}

.color-popup-actions .color-confirm-btn:hover:not(:disabled) {
  background: #76a6f5;
}

.color-popup-actions .color-confirm-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

/* 모달 하단 버튼 */

.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 12px;
}

.modal-actions button {
  padding: 10px 18px;
  border: 0;
  border-radius: 9px;
  cursor: pointer;
}

.cancel-btn {
  background: #f0f2f6;
  color: #505766;
}

.save-btn {
  background: #8bb4f5;
  color: #172b4c;
  font-weight: 700;
}

.save-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.delete-btn {
  margin-right: auto;
  padding: 10px 18px;
  border: 0;
  border-radius: 9px;
  background: #fff0f0;
  color: #d54141;
  font-weight: 600;
  cursor: pointer;
}

.delete-btn:hover {
  background: #ffe0e0;
}

/* 창 이동 잠금 버튼 */

.pin-btn {
  position: absolute;
  top: 5px;
  right: 5px;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: 1px solid rgb(130 140 155 / 20%);
  border-radius: 8px;
  background: rgb(255 255 255 / 75%);
  font-size: 16px;
  cursor: pointer;
  -webkit-app-region: no-drag;
}

.pin-btn:hover {
  background: #e9efff;
}

/* 작은 화면 대응 */

@media (max-width: 500px) {
  .app {
    padding: 8px;
  }

  .calendar-day,
  .empty-day {
    min-height: 46px;
  }

  .event-modal {
    padding: 16px;
  }
}

/* 메인 달력 화면의 스크롤바 숨기기 */
html,
body,
#root,
.app {
  scrollbar-width: none; /* Firefox */
  -ms-overflow-style: none; /* 구형 Edge */
}

html::-webkit-scrollbar,
body::-webkit-scrollbar,
#root::-webkit-scrollbar,
.app::-webkit-scrollbar {
  display: none; /* Chrome, Electron */
}



/* 앱 종료 버튼: 오른쪽 */
.quit-btn {
  right: 5px;
  background: transparent !important;
  border-color: transparent !important;
  box-shadow: none !important;
  color: #D94A4A;
}

.quit-btn:hover {
  background: rgb(217 74 74 / 10%) !important;
  color: #C53535;
}

/* 창 고정 버튼: 종료 버튼 왼쪽으로 이동 */
.calendar-header > .pin-btn:not(.quit-btn) {
  right: 41px;
